    "      <div class=\"kicker\">documentação</div>\n"
    "      <h2>Como usar</h2>\n"
    "\n"
    "      <h3>Primeiro uso</h3>\n"
    "      <p>Abra um terminal novo e digite <code>delta</code>. Na primeira vez, conecte um provedor:</p>\n"
    "      <div class=\"cmdblock\">\n"
    "        <div><b>/login</b> <span class=\"c\"># lista os provedores, pede a chave e escolhe um modelo</span></div>\n"
    "        <div><b>/projects</b> D:\\dev\\meu-app <span class=\"c\"># passa a trabalhar nessa pasta (fica salvo)</span></div>\n"
    "        <div><span class=\"c\"># agora é só escrever o que você quer</span></div>\n"
    "        <div><b>leia src/main.c e explique o fluxo</b></div>\n"
    "      </div>\n"
    "\n"
    "      <h3>Retomar o trabalho</h3>\n"
    "      <p>O <code>delta</code> <b>abre no último chat daquela pasta</b>: você continua de onde parou,\n"
    "         com o histórico e o contexto. <code>delta --new</code> começa do zero e <code>/new</code>\n"
    "         faz o mesmo de dentro da sessão.</p>\n"
    "\n"
    "      <h3>Comandos</h3>\n"
    "      <div class=\"kv\">\n"
    "        <b>/login</b><span>escolhe provedor e cola a chave</span>\n"
    "        <b>/models</b><span>modelos dos provedores conectados</span>\n"
    "        <b>/thinking</b><span>esforço de raciocínio</span>\n"
    "        <b>/projects</b><span>pasta onde ele trabalha</span>\n"
    "        <b>/terminal</b><span>roda um comando no shell e mostra a saída</span>\n"
    "        <b>/copy</b><span>copia a última resposta</span>\n"
    "        <b>/status</b><span>configuração e uso</span>\n"
    "        <b>/help</b><span>todos os comandos e atalhos</span>\n"
    "      </div>\n"
    "\n"
    "      <h3>Atalhos</h3>\n"
    "      <div class=\"kv\">\n"
    "        <b>Enter</b><span>envia (durante o trabalho: entra na fila e ele lê no meio do turno)</span>\n"
    "        <b>Shift+Enter</b><span>quebra a linha</span>\n"
    "        <b>Ctrl+C</b><span>interrompe a geração (não fecha o app)</span>\n"
    "        <b>Ctrl+X</b><span>copia a última resposta</span>\n"
    "        <b>Ctrl+Q</b><span>devolve a última mensagem da fila ao editor</span>\n"
    "        <b>mouse</b><span>arrastar seleciona e copia; roda rola a conversa</span>\n"
    "        <b>Esc</b><span>limpa a seleção e volta ao fim</span>\n"
    "      </div>\n"
    "\n"
    "      <h3>Seu sistema</h3>\n"
    "      <p>Escreva em <code>system/prompt.md</code> (dentro da pasta de dados) o que o Delta deve\n"
    "         obedecer em toda conversa: tom, formato, regras do time. Ele relê o arquivo a cada turno.</p>\n"
    "\n"
    "      <h3>Problemas comuns</h3>\n"
    "      <ul>\n"
    "        <li><b>“sem chave de API”</b> — rode <code>/login</code> ou defina\n"
    "            <code>OPENAI_API_KEY</code> / <code>ANTHROPIC_API_KEY</code>.</li>\n"
    "        <li><b>“catalogo indisponivel”</b> — sem rede na primeira execução; tente de novo.</li>\n"
    "        <li><b><code>delta</code> não é reconhecido</b> — abra um terminal novo (o PATH foi\n"
    "            atualizado) ou use o caminho completo que aparece na instalação.</li>\n"
    "        <li><b>SmartScreen na primeira execução</b> — “Mais informações → Executar assim mesmo”.</li>\n"
    "      </ul>\n"
    "    </div>\n"
    "  </section>\n"
    "\n"
    "</main>\n"
    "\n"
    "<footer>\n"
    "  <div class=\"foot\">\n"
    "    <span>Delta Agent · <span id=\"exeHint\"></span></span>\n"
    "    <span><a href=\"#/o-que-e\">o que é</a> · <a href=\"#/como-usar\">como usar</a></span>\n"
    "  </div>\n"
    "</footer>\n"
    "\n"
    "<script>\n"
    "const $ = (s) => document.querySelector(s);\n"
    "const $$ = (s) => document.querySelectorAll(s);\n"
    "let state = {};\n"
    "\n"
    "/* ---------- rotas: /#/instalar · /#/o-que-e · /#/como-usar ---------- */\n"
    "function show(view) {\n"
    "  if (!document.querySelector('.view[data-view=\"' + view + '\"]')) view = 'instalar';\n"
    "  $$('.view').forEach(v => v.classList.toggle('on', v.dataset.view === view));\n"
    "  $$('nav a').forEach(a => a.classList.toggle('on', a.dataset.go === view));\n"
    "  window.scrollTo({ top: 0 });\n"
    "}\n"
    "function route() {\n"
    "  const h = (location.hash || '').replace(/^#\\/?/, '');\n"
    "  show(h || 'instalar');\n"
    "}\n"
    "window.addEventListener('hashchange', route);\n"
    "\n"
    "async function api(path, body) {\n"
    "  const r = await fetch(path, {\n"
    "    method: body ? 'POST' : 'GET',\n"
    "    headers: body ? { 'content-type': 'application/json' } : {},\n"
    "    body: body ? JSON.stringify(body) : undefined,\n"
    "  });\n"
    "  const txt = await r.text();\n"
    "  try { return JSON.parse(txt); } catch { return { ok: false, error: txt }; }\n"
    "}\n"
    "\n"
    "function addStep(html, cls) {\n"
    "  const li = document.createElement('li');\n"
    "  li.innerHTML = html;\n"
    "  if (cls) li.className = cls;\n"
    "  $('#log').appendChild(li);\n"
    "  return li;\n"
    "}\n"
    "\n"
    "async function boot() {\n"
    "  state = await api('/api/state');\n"
    "  if (state.os) $('#osName').textContent = state.os;\n"
    "  if (state.version) $('#verBadge').textContent = 'v' + state.version;\n"
    "  if (state.defaultDir) $('#dir').value = state.defaultDir;\n"
    "  if (state.exe) $('#exeHint').textContent = state.exe;\n"
    "\n"
    "  /* `delta wiki` abre em /wiki: cai direto na documentação */\n"
    "  if (!location.hash && /^\\/(wiki|docs)/.test(location.pathname)) {\n"
    "    location.replace(location.pathname.replace(/\\/$/, '') + '#/o-que-e');\n"
    "    return;\n"
    "  }\n"
    "  route();\n"
    "}\n"
    "\n"
    "$('#pick').onclick = async () => {\n"
    "  const b = $('#pick');\n"
    "  b.disabled = true; b.textContent = 'aguardando…';\n"
    "  const r = await api('/api/pick', {});\n"
    "  b.disabled = false; b.textContent = 'Escolher pasta…';\n"
    "  if (r.dir) {\n"
    "    $('#dir').value = r.dir;\n"
    "    $('#msg').innerHTML = 'pasta escolhida: <b>' + r.dir + '</b>';\n"
    "  }\n"
    "};\n"
    "\n"
    "$('#go').onclick = async () => {\n"
    "  const dir = $('#dir').value.trim();\n"
    "  if (!dir) { $('#dir').focus(); return; }\n"
    "  $('#form').style.display = 'none';\n"
    "  $('#guide').style.display = 'none';\n"
    "  $('#okpanel').style.display = 'none';\n"
    "  $('#log').style.display = '';\n"
    "  $('#log').innerHTML = '';\n"
    "  addStep('instalando em <b>' + dir + '</b>…', 'run');\n"
    "  const r = await api('/api/install', { dir });\n"
    "  $('#log').innerHTML = '';\n"
    "  (r.steps || []).forEach(s => addStep(s.text, s.ok ? 'ok' : 'err'));\n"
    "\n"
    "  if (!r.ok) {\n"
    "    addStep(r.error || 'não deu para instalar', 'err');\n"
    "    const b = document.createElement('button');\n"
    "    b.textContent = 'Voltar'; b.className = 'primary'; b.style.marginTop = '14px';\n"
    "    b.onclick = () => { $('#log').style.display = 'none'; $('#form').style.display = ''; };\n"
    "    $('#log').appendChild(b);\n"
    "    return;\n"
    "  }\n"
    "\n"
    "  /* feedback de instalado, aqui mesmo, depois de escolher a pasta */\n"
    "  $('#log').style.display = 'none';\n"
    "  $('#okpanel').style.display = '';\n"
    "  $('#guide').style.display = '';\n"
    "  const pin = r.pinned === 'taskbar' ? 'fixado na barra de tarefas'\n"
    "            : r.pinned === 'dock-apps' ? 'no dock'\n"
    "            : r.pinned === 'shortcut' ? 'atalho criado' : 'fixe manualmente';\n"
    "  $('#paths').innerHTML =\n"
    "    'dados&nbsp;&nbsp;&nbsp; <b>' + r.coreDir + '</b><br>' +\n"
    "    'programa <b>' + r.exePath + '</b><br>' +\n"
    "    'comando&nbsp; <b>delta</b> → ' + r.resolved +\n"
    "    ' <span class=\"c\">(' + pin + ')</span>';\n"
    "};\n"
    "\n"
    "$('#again').onclick = () => {\n"
    "  $('#okpanel').style.display = 'none';\n"
    "  $('#guide').style.display = 'none';\n"
    "  $('#log').style.display = 'none';\n"
    "  $('#form').style.display = '';\n"
    "  $('#msg').innerHTML = '';\n"
    "  window.scrollTo({ top: 0, behavior: 'smooth' });\n"
    "};\n"
    "\n"
    "$('#close').onclick = async () => {\n"
    "  await api('/api/quit', {});\n"
    "  document.body.innerHTML =\n"
    "    '<div style=\"max-width:820px;margin:0 auto;padding:90px 24px;text-align:center\">' +\n"
    "    '<div style=\"font:400 46px/1 Georgia,serif\">Δ</div>' +\n"
    "    '<h2 style=\"font:400 30px/1.2 Georgia,serif;margin:20px 0 8px\">Pode fechar esta aba</h2>' +\n"
    "    '<p style=\"color:#71717a;font:13px ui-monospace,monospace\">instalador encerrado · abra um terminal e digite delta</p>' +\n"
    "    '</div>';\n"
    "};\n"
    "\n"
    "boot();\n"
    "</script>\n"
    "</body>\n"
    "</html>\n"
    "\n"
;

#endif /* DELTA_INSTALLER_HTML_H */
